            "type": 2,
            "multiSelect": true,
            "quote": "'",
            "delimiter": ",",
            "isRequired": true,
            "query": "resourcecontainers\n| where type =~ 'microsoft.resources/subscriptions'\n| where properties.state =~ 'Enabled'\n| project value = id, label = name, selected = true\n| order by label asc",
            "queryType": 1,
            "resourceType": "microsoft.resourcegraph/resources",
