            "quote": "'",
            "delimiter": ",",
            "query": "resources\n| where type =~ 'microsoft.web/sites'\n| where kind contains 'functionapp'\n| where kind !contains 'workflowapp'\n| summarize Apps = count() by resourceGroup\n| project value = resourceGroup, label = strcat(resourceGroup, ' (', Apps, ')'), selected = false\n| order by label asc",
