                             pack_array('Daily memory quota cap set'), dynamic([])),\n    iff(clientCert != true and isempty(subnetId),        pack_array('No client certificate requirement'), dynamic([]))\n  )\n| extend IssueCount = array_length(IssueList)\n| extend Issues     = strcat_array(IssueList, ' | ')\n| extend Severity = case(\n      isLinuxConsumption == true and IssueCount >= 3, 'Critical',\n      isLinuxConsumption == true,                     'High',\n      IssueCount >= 5,                                'High',\n      IssueCount >= 2,                                'Medium',\n      IssueCount >= 1,                                'Low',\n                                                      'Healthy')\n| extend SeverityRank = case(Severity == 'Critical', 0, Severity == 'High', 1, Severity == 'Medium', 2, Severity == 'Low', 3, 4)\n| summarize Apps = count() by Severity, SeverityRank\n| order by SeverityRank asc\n| project Severity, Apps",
