            "name": "Consumptionplans"
          }
        ]
      },
      "conditionalVisibility": {
        "parameterName": "selectedTab",
        "comparison": "isEqualTo",
        "value": "retirement"
      },
      "name": "group-retirement"
    },
    {
      "type": 12,
      "content": {
        "version": "NotebookGroup/1.0",
        "groupType": "editable",
        "items": [
          {
            "type": 1,
            "content": {
              "json": "## Configuration posture\r\n\r\nEvery column below is backed by a property that Azure Resource Graph genuinely\r\npopulates for `microsoft.web/sites`. Settings that Resource Graph leaves null\r\n(minimum TLS version, FTPS state, CORS origins, IP restrictions, remote debugging,\r\nhealth-check path) are deliberately **omitted** rather than displayed as \"Unknown\" -\r\nuse `Get-FunctionAppDeepConfig.ps1` to collect those through the ARM control plane."
            },
            "name": "cfgHeader"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\n| where type =~ 'microsoft.web/sites'\n| where kind contains 'functionapp'\n| where kind !contains 'workflowapp'\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _apps = dynamic([{FunctionApps}])\n| where array_length(_apps) == 0 or set_has_element(_apps, '*') or set_has_element(_apps, tolower(id))\n| extend planId    = tolower(tostring(properties.serverFarmId))\n| extend tier      = tostring(properties.sku)\n| extend isLinux   = tobool(properties.reserved)\n| extend osType    = iff(isLinux == true or kind contains 'linux', 'Linux', 'Windows')\n| extend state     = tostring(properties.state)\n| extend enabledFlag = tobool(properties.enabled)\n| extend httpsOnly = tobool(properties.httpsOnly)\n| extend pna       = tostring(properties.publicNetworkAccess)\n| extend subnetId  = tostring(properties.virtualNetworkSubnetId)\n| extend availability = tostring(properties.availabilityState)\n| extend usage     = tostring(properties.usageState)\n| extend identityType = tostring(identity.type)\n| extend clientCert = tobool(properties.clientCertEnabled)\n| extend defaultHost = tostring(properties.defaultHostName)\n| extend memQuota  = toint(properties.dailyMemoryTimeQuota)\n| extend redundancy = tostring(properties.redundancyMode)\n| extend lastModified = todatetime(properties.lastModifiedTimeUtc)\n| extend alwaysOn  = tobool(properties.siteConfig.alwaysOn)\n| extend http2     = tobool(properties.siteConfig.http20Enabled)\n| extend linuxFx   = tostring(properties.siteConfig.linuxFxVersion)\n| extend scaleLimit = toint(properties.siteConfig.functionAppScaleLimit)\n| extend isConsumption = (tier =~ 'Dynamic')\n| extend isFlex        = (tier =~ 'FlexConsumption')\n| extend isServerless  = (isConsumption or isFlex)\n| extend TierLabel = case(\n      tier =~ 'Dynamic',         'Consumption (Y1)',\n      tier =~ 'FlexConsumption', 'Flex Consumption',\n      tier =~ 'ElasticPremium',  'Premium (Elastic)',\n      isempty(tier),             'Unknown',\n      tier)\n| extend isLinuxConsumption = (isConsumption and osType == 'Linux')\n| join kind=leftouter (\n    resources\n    | where type =~ 'microsoft.web/serverfarms'\n    | project planId = tolower(id),\n              planName = name,\n              planSkuName = tostring(sku.name),\n              planSkuTier = tostring(sku.tier),\n              planCapacity = toint(sku.capacity),\n              planZoneRedundant = tobool(properties.zoneRedundant)\n  ) on planId\n| join kind=leftouter (\n    resourcecontainers\n    | where type =~ 'microsoft.resources/subscriptions'\n    | project subscriptionId, Subscription = name\n  ) on subscriptionId\n| extend SkuDisplay = strcat(coalesce(planSkuTier, tier), iff(isnotempty(planSkuName), strcat(' (', planSkuName, ')'), ''))\n| project\n    ['Function app'] = name,\n    Subscription,\n    ['Resource group'] = resourceGroup,\n    ['HTTPS only'] = iff(httpsOnly == true, 'Yes', 'No'),\n    ['Client cert'] = case(isnull(clientCert), 'Unknown', clientCert == true, 'Required', 'Not required'),\n    ['Managed identity'] = iff(isempty(identityType) or identityType =~ 'None', 'None', identityType),\n    ['Public network access'] = iff(isempty(pna), 'Unknown', pna),\n    ['VNet integrated'] = iff(isnotempty(subnetId), 'Yes', 'No'),\n    ['HTTP/2'] = case(isnull(http2), 'Unknown', http2 == true, 'Enabled', 'Disabled'),\n    ['Availability'] = iff(isempty(availability), 'Unknown', availability),\n    ResourceId = id\n| order by ['HTTPS only'] asc, ['Function app'] asc",
              "size": 2,
              "title": "Security and access",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "showExportToExcel": true,
              "gridSettings": {
                "rowLimit": 1000,
                "filter": true
              }
            },
            "name": "Securityandaccess"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\n| where type =~ 'microsoft.web/sites'\n| where kind contains 'functionapp'\n| where kind !contains 'workflowapp'\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _apps = dynamic([{FunctionApps}])\n| where array_length(_apps) == 0 or set_has_element(_apps, '*') or set_has_element(_apps, tolower(id))\n| extend planId    = tolower(tostring(properties.serverFarmId))\n| extend tier      = tostring(properties.sku)\n| extend isLinux   = tobool(properties.reserved)\n| extend osType    = iff(isLinux == true or kind contains 'linux', 'Linux', 'Windows')\n| extend state     = tostring(properties.state)\n| extend enabledFlag = tobool(properties.enabled)\n| extend httpsOnly = tobool(properties.httpsOnly)\n| extend pna       = tostring(properties.publicNetworkAccess)\n| extend subnetId  = tostring(properties.virtualNetworkSubnetId)\n| extend availability = tostring(properties.availabilityState)\n| extend usage     = tostring(properties.usageState)\n| extend identityType = tostring(identity.type)\n| extend clientCert = tobool(properties.clientCertEnabled)\n| extend defaultHost = tostring(properties.defaultHostName)\n| extend memQuota  = toint(properties.dailyMemoryTimeQuota)\n| extend redundancy = tostring(properties.redundancyMode)\n| extend lastModified = todatetime(properties.lastModifiedTimeUtc)\n| extend alwaysOn  = tobool(properties.siteConfig.alwaysOn)\n| extend http2     = tobool(properties.siteConfig.http20Enabled)\n| extend linuxFx   = tostring(properties.siteConfig.linuxFxVersion)\n| extend scaleLimit = toint(properties.siteConfig.functionAppScaleLimit)\n| extend isConsumption = (tier =~ 'Dynamic')\n| extend isFlex        = (tier =~ 'FlexConsumption')\n| extend isServerless  = (isConsumption or isFlex)\n| extend TierLabel = case(\n      tier =~ 'Dynamic',         'Consumption (Y1)',\n      tier =~ 'FlexConsumption', 'Flex Consumption',\n      tier =~ 'ElasticPremium',  'Premium (Elastic)',\n      isempty(tier),             'Unknown',\n      tier)\n| extend isLinuxConsumption = (isConsumption and osType == 'Linux')\n| join kind=leftouter (\n    resources\n    | where type =~ 'microsoft.web/serverfarms'\n    | project planId = tolower(id),\n              planName = name,\n              planSkuName = tostring(sku.name),\n              planSkuTier = tostring(sku.tier),\n              planCapacity = toint(sku.capacity),\n              planZoneRedundant = tobool(properties.zoneRedundant)\n  ) on planId\n| join kind=leftouter (\n    resourcecontainers\n    | where type =~ 'microsoft.resources/subscriptions'\n    | project subscriptionId, Subscription = name\n  ) on subscriptionId\n| extend SkuDisplay = strcat(coalesce(planSkuTier, tier), iff(isnotempty(planSkuName), strcat(' (', planSkuName, ')'), ''))\n| project\n    ['Function app'] = name,\n    Subscription,\n    ['Resource group'] = resourceGroup,\n    Plan = coalesce(planName, '-'),\n    Tier = TierLabel,\n    SKU = coalesce(planSkuName, 'Unknown'),\n    Instances = coalesce(planCapacity, 0),\n    ['Zone redundant'] = case(isnull(planZoneRedundant), 'Unknown', planZoneRedundant == true, 'Yes', 'No'),\n    ['Always On'] = case(isServerless, 'N/A (serverless)', isnull(alwaysOn), 'Unknown', alwaysOn == true, 'Yes', 'No'),\n    ['Scale limit'] = coalesce(scaleLimit, 0),\n    OS = osType,\n    ['Runtime stack'] = iff(isempty(linuxFx), 'Unknown (Windows or not indexed)', linuxFx),\n    ['Redundancy mode'] = iff(isempty(redundancy), 'Unknown', redundancy),\n    ['Last modified'] = lastModified,\n    ResourceId = id\n| order by Instances desc, ['Scale limit'] desc, Tier asc, ['Function app'] asc",
              "size": 2,
              "title": "Hosting and scale",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "showExportToExcel": true,
              "gridSettings": {
                "rowLimit": 1000,
                "filter": true,
                "sortBy": [
                  {
                    "itemKey": "Instances",
                    "sortOrder": 2
                  },
                  {
                    "itemKey": "Scale limit",
                    "sortOrder": 2
                  }
                ]
              }
            },
            "name": "Hostingandscale"
          },
          {
            "type": 1,
            "content": {
              "json": "### Deployment slots"
            },
            "name": "slotHdr"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\n| where type =~ 'microsoft.web/sites/slots'\n| where kind contains 'functionapp'\n| extend siteKey = tolower(tostring(split(id, '/slots/')[0]))\n| join kind=inner (\n    resources\n| where type =~ 'microsoft.web/sites'\n| where kind contains 'functionapp'\n| where kind !contains 'workflowapp'\n    | extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n    | join kind=leftouter (\n    resourcecontainers\n    | where type =~ 'microsoft.resources/subscriptions'\n    | project subscriptionId, Subscription = name\n  ) on subscriptionId\n    | project siteKey = tolower(id), appName = name, appSubscription = Subscription, appRg = resourceGroup\n  ) on siteKey\n| project\n    ['Function app'] = appName,\n    Subscription = appSubscription,\n    ['Resource group'] = appRg,\n    ['Slot'] = tostring(split(name, '/')[-1]),\n    State = tostring(properties.state),\n    ['HTTPS only'] = iff(tobool(properties.httpsOnly) == true, 'Yes', 'No'),\n    ResourceId = id\n| order by ['Function app'] asc",
              "size": 2,
              "title": "Function App slots",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "showExportToExcel": true,
              "gridSettings": {
                "rowLimit": 1000,
                "filter": true
              }
            },
            "name": "FunctionAppslots"
          }
        ]
      },
      "conditionalVisibility": {
        "parameterName": "selectedTab",
        "comparison": "isEqualTo",
        "value": "config"
      },
      "name": "group-config"
    },
    {
      "type": 12,
      "content": {
        "version": "NotebookGroup/1.0",
        "groupType": "editable",
        "items": [
          {
            "type": 1,
            "content": {
              "json": "## Azure Advisor and Resource Health\r\n\r\nThese panels read the `advisorresources` and `healthresources` tables. They are\r\nempty when no recommendations or health events exist for the selected apps, which\r\nis a valid healthy result rather than an error."
            },
            "name": "advHeader"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "advisorresources\n| where type =~ 'microsoft.advisor/recommendations'\n| extend targetId = tolower(tostring(properties.resourceMetadata.resourceId))\n| join kind=inner (\n    resources\n| where type =~ 'microsoft.web/sites'\n| where kind contains 'functionapp'\n| where kind !contains 'workflowapp'\n    | extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n    | join kind=leftouter (\n    resourcecontainers\n    | where type =~ 'microsoft.resources/subscriptions'\n    | project subscriptionId, Subscription = name\n  ) on subscriptionId\n    | project targetId = tolower(id), appName = name, appSubscription = Subscription, appRg = resourceGroup\n  ) on targetId\n| project\n    ['Function app'] = appName,\n    Subscription = appSubscription,\n    ['Resource group'] = appRg,\n    Category = tostring(properties.category),\n    Impact   = tostring(properties.impact),\n    Problem  = tostring(properties.shortDescription.problem),\n    Solution = tostring(properties.shortDescription.solution),\n    ResourceId = targetId\n| order by Impact asc, ['Function app'] asc",
              "size": 2,
              "title": "Advisor recommendations",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "showExportToExcel": true,
              "gridSettings": {
                "rowLimit": 1000,
                "filter": true
              }
            },
            "name": "Advisorrecommendations"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "healthresources\n| where type =~ 'microsoft.resourcehealth/availabilitystatuses'\n| extend targetId = tolower(tostring(properties.targetResourceId))\n| join kind=inner (\n    resources\n| where type =~ 'microsoft.web/sites'\n| where kind contains 'functionapp'\n| where kind !contains 'workflowapp'\n    | extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n    | join kind=leftouter (\n    resourcecontainers\n    | where type =~ 'microsoft.resources/subscriptions'\n    | project subscriptionId, Subscription = name\n  ) on subscriptionId\n    | project targetId = tolower(id), appName = name, appSubscription = Subscription, appRg = resourceGroup\n  ) on targetId\n| project\n    ['Function app'] = appName,\n    Subscription = appSubscription,\n    ['Resource group'] = appRg,\n    Availability = tostring(properties.availabilityState),\n    Summary = tostring(properties.summary),\n    ['Since'] = todatetime(properties.occuredTime),\n    ResourceId = targetId\n| order by Availability asc",
              "size": 2,
              "title": "Resource health",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "showExportToExcel": true,
              "gridSettings": {
                "rowLimit": 1000,
                "filter": true
              }
            },
            "name": "Resourcehealth"
          }
        ]
      },
      "conditionalVisibility": {
        "parameterName": "selectedTab",
        "comparison": "isEqualTo",
        "value": "advisor"
      },
      "name": "group-advisor"
    },
    {
      "type": 12,
      "content": {
        "version": "NotebookGroup/1.0",
        "groupType": "editable",
        "items": [
          {
            "type": 1,
            "content": {
              "json": "## About the data in this workbook\r\n\r\nEverything here comes from **Azure Resource Graph** (`queryType: 1`). No Log\r\nAnalytics workspace, diagnostic setting or Application Insights resource is\r\nrequired, so the workbook returns results immediately in any subscription.\r\n\r\n### Verified Resource Graph behaviour\r\n\r\nThese findings were measured against live Function App resources, not assumed\r\nfrom ARM template documentation:\r\n\r\n| Source | Availability in Resource Graph |\r\n| --- | --- |\r\n| `microsoft.web/sites` top-level `properties` | Richly populated - the basis of this workbook |\r\n| `properties.siteConfig.alwaysOn`, `.linuxFxVersion`, `.http20Enabled`, `.functionAppScaleLimit` | Populated |\r\n| `properties.siteConfig.minTlsVersion`, `.ftpsState`, `.cors`, `.healthCheckPath`, `.remoteDebuggingEnabled`, `.ipSecurityRestrictions` | Key exists but value is **always null** |\r\n| `microsoft.web/sites/config` | **Not indexed at all** (zero rows) |\r\n| `microsoft.insights/diagnosticsettings` | **Not indexed at all** (zero rows) |\r\n\r\nBecause the second and third rows above cannot be read from Resource Graph, this\r\nworkbook does **not** display TLS, FTPS, CORS, IP-restriction, remote-debugging or\r\nhealth-check columns. Showing them would produce a column reading \"Unknown\" for\r\nevery app. Collect those settings with the companion script\r\n`Get-FunctionAppDeepConfig.ps1`, which calls the ARM control plane per app.\r\n\r\n### How severity is calculated\r\n\r\nLinux Consumption retirement exposure dominates, because it is a hard deadline\r\nrather than a tunable setting:\r\n\r\n| Severity | Condition |\r\n| --- | --- |\r\n| Critical | On Linux Consumption **and** 3 or more other findings |\r\n| High | On Linux Consumption, or 5+ findings |\r\n| Medium | 2-4 findings |\r\n| Low | 1 finding |\r\n| Healthy | No findings |\r\n\r\n### Scope\r\n\r\nAzure Functions only. Logic Apps (Standard) carry `kind = 'functionapp,workflowapp'`\r\nand are explicitly excluded, as are plain App Service web apps.\r\n\r\n### Key retirement dates\r\n\r\n| Date | Event |\r\n| --- | --- |\r\n| 30 September 2026 | Apps on the end-of-life **v3 runtime** on Linux Consumption stop running |\r\n| 30 September 2028 | **Linux Consumption plan retires** |\r\n\r\nReferences:\r\n[Retirement notice](https://azure.microsoft.com/updates/?id=499451) |\r\n[Consumption plan (legacy)](https://learn.microsoft.com/azure/azure-functions/consumption-plan) |\r\n[Flex Consumption plan](https://learn.microsoft.com/azure/azure-functions/flex-consumption-plan) |\r\n[Migration guide](https://learn.microsoft.com/azure/azure-functions/migration/migrate-plan-consumption-to-flex)"
            },
            "name": "aboutText"
          },
          {
            "type": 1,
            "content": {
              "json": "### Support and feedback\r\n\r\nFound an issue, a false positive, or a missing check? Please get in touch - detail\r\nwhich tab and which Function App or plan is involved, and the fix will be turned\r\naround quickly.\r\n\r\n**Bulent Ozkir**\r\n[bulento@microsoft.com](mailto:bulento@microsoft.com) |\r\n[bulentozkir@hotmail.com](mailto:bulentozkir@hotmail.com)\r\n\r\n### License\r\n\r\nCopyright (c) 2026 Bulent Ozkir\r\n\r\nPermission is hereby granted, free of charge, to any person obtaining a copy of this\r\nsoftware and associated documentation files (the \"Software\"), to deal in the Software\r\nwithout restriction, including without limitation the rights to use, copy, modify,\r\nmerge, publish, distribute, sublicense, and/or sell copies of the Software, and to\r\npermit persons to whom the Software is furnished to do so, subject to the following\r\nconditions:\r\n\r\nThe above copyright notice and this permission notice shall be included in all copies\r\nor substantial portions of the Software.\r\n\r\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED,\r\nINCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A\r\nPARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT\r\nHOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF\r\nCONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE\r\nOR THE USE OR OTHER DEALINGS IN THE SOFTWARE.",
              "style": "info"
            },
            "name": "aboutContact"
          }
        ]
      },
      "conditionalVisibility": {
        "parameterName": "selectedTab",
        "comparison": "isEqualTo",
        "value": "about"
